{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Key Vault key is not backed by HSM",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key uses the software-backed RSA key type, which provides less protection against key extraction and tampering than an HSM-backed key."
    },
    {
      "check_id": "CKV_AZURE_40",
      "title": "Key Vault key has no expiration date",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key has no expiration_date, allowing it to remain valid indefinitely if key rotation or replacement is not performed."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_key\" \"generated\" {\n  name            = \"terragoat-generated-certificate-${var.environment}\"\n  key_vault_id    = azurerm_key_vault.example.id\n  key_type        = \"RSA-HSM\"\n  key_size        = 2048\n  expiration_date = \"2030-12-31T23:59:59Z\"\n  key_opts = [\n    \"decrypt\",\n    \"encrypt\",\n    \"sign\",\n    \"unwrapKey\",\n    \"verify\",\n    \"wrapKey\",\n  ]\n}\n",
  "fix_summary": "Changed the key type to RSA-HSM so key operations are hardware-backed and added an explicit expiration date to prevent indefinite key validity."
}
